let currentUser=null,view='billing',state={};
const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=paise=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format((Number(paise)||0)/100);
const badge=s=>`<span class="badge ${escapeHtml(s)}">${escapeHtml(s.replaceAll('_',' '))}</span>`;
const table=(heads,rows)=>rows.length?`<div class="table-wrap"><table class="table"><thead><tr>${heads.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No records in this view yet.</div>';
const panel=(title,subtitle,inside)=>`<section class="card panel"><div class="panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div></div>${inside}</section>`;
async function api(path,method='GET',payload){const response=await fetch('/api'+path,{method,credentials:'same-origin',headers:payload?{'Content-Type':'application/json'}:{},body:payload?JSON.stringify(payload):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data;}
function notice(message){const n=$('#notice');n.textContent=message;n.style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>n.style.display='none',5000);}
async function refresh(){try{const me=await api('/me');currentUser=me.user;$('#login').hidden=true;$('#workspace').hidden=false;$('#identity').innerHTML=`<span>${escapeHtml(currentUser.name)}</span><button id="logout">Sign out</button>`;$('#role-label').textContent=currentUser.role.toUpperCase()+' WORKSPACE';const [plans,subscriptions,invoices,usage,health]=await Promise.all([api('/plans'),api('/subscriptions'),api('/invoices'),api('/usage'),api('/health')]);state={plans:plans.plans,subscriptions:subscriptions.subscriptions,invoices:invoices.invoices,usage:usage.usage,health};if(view==='audit'&&currentUser.role==='operator')state.audit=(await api('/audit')).audit;render();}catch(e){if(e.message==='Sign in required'){$('#login').hidden=false;$('#workspace').hidden=true;currentUser=null}else notice(e.message)}}
function render(){document.querySelectorAll('#tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===view);});$('#content').innerHTML=({billing:billingView,audit:auditView,agent:agentView})[view]();}
function billingView(){const operator=currentUser.role==='operator';const plans=panel('Monthly plans','GST included · first month charged at checkout · hard limits with upgrade prompts',`<div>${state.plans.map(p=>{const l=JSON.parse(p.limits_json||'{}');return `<div class="plan-item"><div><strong>${escapeHtml(p.name)} · ${money(p.amount_paise)}/mo</strong><small>${l.team_members||0} team · ${l.websites||0} websites · ${(l.crm_contacts||0).toLocaleString()} contacts · ${(l.ai_credits||0).toLocaleString()} AI credits</small><small>Razorpay plan: ${p.razorpay_plan_id?escapeHtml(p.razorpay_plan_id):'not linked'}</small></div>${operator?`<button data-action="link-plan" data-id="${p.id}">Link test plan</button>`:''}</div>`}).join('')}</div>${operator?`<button class="primary" data-action="provision-plans">Create and link Razorpay test plans</button>`:''}`);
const subs=panel('Subscriptions','All demo records; manage Razorpay subscriptions directly',table(['CUSTOMER','PLAN','STATUS','PERIOD END','ACTION'],state.subscriptions.map(s=>[escapeHtml(s.customer_email),escapeHtml(s.plan_name)+' · '+money(s.amount_paise),badge(s.status),escapeHtml(s.current_period_end||'Awaiting provider'),s.provider_subscription_id&&!['canceled','cancelled'].includes(s.status)?`<div class="actions"><button data-action="change" data-id="${s.id}">Change plan</button><button data-action="cancel" data-id="${s.id}">Cancel now</button></div>`:'—'])));
const invoice=panel('Invoices','Razorpay webhook outcomes are authoritative for provider payments',table(['INVOICE','CUSTOMER','AMOUNT','STATUS'],state.invoices.map(i=>[escapeHtml(i.provider_invoice_id||i.id),escapeHtml(i.customer_email),money(i.amount_paise),badge(i.status)])));
const usage=panel('Usage records','Timestamped metered consumption',table(['METER','QUANTITY','SOURCE','RECORDED'],state.usage.map(u=>[escapeHtml(u.meter),Number(u.quantity).toLocaleString(),escapeHtml(u.source_event_id),escapeHtml(u.created_at.slice(0,16))]))+(operator?`<form id="usage-form"><label>Subscription<select name="subscription_id">${state.subscriptions.map(s=>`<option value="${s.id}">${escapeHtml(s.customer_email)} · ${escapeHtml(s.plan_name)}</option>`).join('')}</select></label><div class="form-row"><label>Meter<input name="meter" required placeholder="api_calls"></label><label>Quantity<input name="quantity" type="number" min="0" required></label></div><label>Unique source event ID<input name="source_event_id" required placeholder="usage-event-001"></label><button>Record usage</button></form>`:''));
const existingSubscription=state.subscriptions.find(s=>s.customer_email===currentUser.email&&!['canceled','demo_canceled'].includes(s.status));
const request=existingSubscription?.provider_subscription_id&&existingSubscription.status==='created'?panel('Continue checkout','Your Razorpay test subscription is ready.',`<button class="primary" data-action="resume-checkout" data-id="${escapeHtml(existingSubscription.plan_id)}">Open test subscription link</button>`):existingSubscription?'':panel('Buy a subscription','Choose a monthly plan and continue directly to Razorpay Test Mode checkout.',`<form id="subscribe-form"><label>Monthly plan<select name="plan_id">${state.plans.map(p=>`<option value="${p.id}">${escapeHtml(p.name)} · ${money(p.amount_paise)}</option>`).join('')}</select></label><button class="primary">Continue to checkout</button></form><p class="hint">The full first month is charged at checkout. Recurring charges begin 30 days later.</p>`);
return `<div class="grid"><div>${plans}${subs}${request}</div><div>${invoice}${usage}</div></div>`;}
function auditView(){return panel('Audit trail','Recent saved security and billing events',table(['TIME','ACTOR','ACTION','TARGET','DETAILS'],(state.audit||[]).map(a=>[escapeHtml(a.at.slice(0,19)),escapeHtml(a.actor_id||'Provider / system'),escapeHtml(a.action),escapeHtml(a.target||'—'),escapeHtml(a.details.slice(0,140))])));}
function agentView(){return panel('Gemini workflow planner','Draft plans only. Billing actions are handled directly in Nexus.',`<form id="agent-form"><label>Business goal<textarea name="goal" required maxlength="1000" placeholder="Plan a follow-up for webinar attendees"></textarea></label><button class="primary">Draft plan</button></form><p class="hint">Gemini key: ${state.health.geminiConfigured?'configured':'not configured'} · A draft cannot approve, charge, send, or publish.</p><div id="agent-result"></div>`);}
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){view=tab.dataset.tab;await refresh();return}if(e.target.id==='logout'){await api('/logout','POST');currentUser=null;await refresh();return}const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,target=button.dataset.id;try{if(action==='provision-plans'){if(!confirm('Create any unlinked Nexus plans in Razorpay Test Mode?'))return;await api('/admin/provision-razorpay-plans','POST',{});}if(action==='link-plan'){const value=prompt('Razorpay test plan ID (plan_...)');if(!value)return;await api(`/plans/${encodeURIComponent(target)}/razorpay-plan`,'POST',{razorpay_plan_id:value});}if(action==='change'){const plan=prompt('Target plan ID: '+state.plans.map(p=>`${p.id} (${p.name})`).join(', '));if(!plan)return;const result=await api(`/subscriptions/${target}/change`,'POST',{plan_id:plan});notice(result.notice);await refresh();return}if(action==='cancel'){if(!confirm('Cancel this Razorpay test subscription immediately? Remaining paid time is forfeited and no refund is issued.'))return;const result=await api(`/subscriptions/${target}/cancel`,'POST');notice(result.notice);await refresh();return}if(action==='resume-checkout'){const result=await api('/subscriptions/checkout','POST',{plan_id:target});location.href=result.url;return}notice('Action completed');await refresh();}catch(err){notice(err.message)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['login-form','plan-form','usage-form','subscribe-form','agent-form'].includes(form.id))return;e.preventDefault();try{const x=Object.fromEntries(new FormData(form));if(form.id==='login-form'){await api('/login','POST',{email:x.email,password:x.password});}if(form.id==='plan-form'){await api('/plans','POST',{name:x.name,amount_paise:Math.round(Number(x.amount)*100),included_units:Number(x.included_units)});}if(form.id==='usage-form'){await api('/usage','POST',{subscription_id:x.subscription_id,meter:x.meter,quantity:Number(x.quantity),source_event_id:x.source_event_id});}if(form.id==='subscribe-form'){const result=await api('/subscriptions/checkout','POST',{plan_id:x.plan_id});location.href=result.url;return}if(form.id==='agent-form'){const result=await api('/agent/draft','POST',{goal:x.goal});$('#agent-result').textContent=result.draft;notice('Draft created; no action executed');return}notice('Saved');await refresh();}catch(err){notice(err.message)}});
refresh();



